import random, json, sys, subprocess, itertools
sys.path.insert(0,'/workspace/tmp')
import ref

def gen_instance(rnd):
    nn = rnd.randint(2,4)
    nodes = ['n%d'%i for i in range(nn)]
    # edges
    ne = rnd.randint(0,4)
    edges=[]
    ei=0
    for _ in range(ne):
        a=rnd.choice(nodes); b=rnd.choice(nodes)
        if a==b: continue
        edges.append({'id':'e%d'%ei,'source':a,'target':b,'capacity':rnd.choice([0,1,2,3,5,10])})
        ei+=1
    edge_by={e['id']:e for e in edges}
    nc = rnd.randint(0,2)
    commodities=[]
    pairs=set()
    for i in range(nc):
        for _ in range(10):
            a=rnd.choice(nodes); b=rnd.choice(nodes)
            if a==b or (a,b) in pairs: continue
            # find a path
            paths=[]
            def dfs(cur, path, seen):
                if len(paths)>=4: return
                if cur==b:
                    paths.append(list(path)); return
                if len(path)>=3: return
                for e in edges:
                    if e['source']==cur and e['target'] not in seen:
                        dfs(e['target'], path+[e], seen|{e['target']})
            dfs(a,[],{a})
            if paths:
                p=rnd.choice(paths)
                # maybe split into 2 routes
                routes=[]
                if len(p)>1 and rnd.random()<0.4:
                    k=rnd.randrange(1,len(p))
                    routes.append({'edges':[e['id'] for e in p[:k]],'weight':rnd.randint(1,2)})
                    routes.append({'edges':[e['id'] for e in p[k:]],'weight':rnd.randint(1,2)})
                else:
                    routes.append({'edges':[e['id'] for e in p],'weight':rnd.randint(1,3)})
                if sum(r['weight'] for r in routes)<=8:
                    commodities.append({'id':'c%d'%i,'source':a,'target':b,'routes':routes})
                    pairs.add((a,b)); break
    nd = rnd.randint(0,3)
    domains=['d%d'%i for i in range(nd)]
    ns = rnd.randint(1,2)
    snapshots=[]
    for si in range(ns):
        bounds=[[rnd.randint(0,3), rnd.randint(0,4)] for _ in commodities]
        bounds=[[min(b),max(b)] for b in bounds]
        ctrl=[rnd.randint(0,4) for _ in commodities]
        tol=rnd.choice([0,0,1,2])
        obs=[]
        oi=0
        for _ in range(rnd.randint(0,5)):
            kind=rnd.choice(['demand','link','ingress','egress','none'])
            if kind=='demand' and commodities: t=rnd.choice(commodities)['id']
            elif kind=='link' and edges: t=rnd.choice(edges)['id']
            elif kind in ('ingress','egress'): t=rnd.choice(nodes)
            else: continue
            lo=rnd.randint(-1,4); hi=rnd.randint(lo,5)
            dom=rnd.choice(domains+[None]) if domains else None
            obs.append({'id':'o%d'%oi,'metric':kind,'target':t,'lower':lo,'upper':hi,'domain':dom})
            oi+=1
        snapshots.append({'id':'s%d'%si,'bounds':bounds,'controller':ctrl,'tolerance':tol,'observations':obs})
    return {'id':'t','version':1,'nodes':nodes,'edges':edges,'commodities':commodities,
            'domains':domains,'max_faults':rnd.randint(0,nd),'snapshots':snapshots}

def main():
    seed0=int(sys.argv[1]) if len(sys.argv)>1 else 0
    N=int(sys.argv[2]) if len(sys.argv)>2 else 200
    rnd=random.Random(seed0)
    instances=[gen_instance(rnd) for _ in range(N)]
    # batch through the analyzer
    inp='\n'.join(json.dumps(x) for x in instances)+'\n'
    p=subprocess.run(['/workspace/submission/run.sh'],input=inp,text=True,capture_output=True,timeout=600)
    if p.returncode!=0:
        print('RUN FAILED', p.stderr[-3000:]); return 1
    outs=[json.loads(l) for l in p.stdout.splitlines()]
    assert len(outs)==len(instances), (len(outs),len(instances))
    bad=0
    for x,a in zip(instances,outs):
        r=ref.solve(x)
        if r['status']=='infeasible':
            if a.get('status')!='infeasible':
                print('MISMATCH status', x['id'], a.get('status'), 'expected infeasible'); print(json.dumps(x)); bad+=1
            continue
        if a.get('status') in ('error','infeasible'):
            print('MISMATCH err', json.dumps(x)); print(a); bad+=1; continue
        probs=[]
        if a['min_faults']!=r['min_faults']: probs.append(('k',a['min_faults'],r['min_faults']))
        if sorted(a['faults']['forced'])!=r['faults']['forced']: probs.append(('forced',a['faults']['forced'],r['faults']['forced']))
        if sorted(a['faults']['possible'])!=r['faults']['possible']: probs.append(('possible',a['faults']['possible'],r['faults']['possible']))
        if a['status']!=r['status']: probs.append(('status',a['status'],r['status']))
        for si in range(len(x['snapshots'])):
            if a['snapshots'][si]['demands']!=r['demands'][si]: probs.append(('demands',si,a['snapshots'][si]['demands'],r['demands'][si]))
            if a['snapshots'][si]['links']!=r['links'][si]: probs.append(('links',si,a['snapshots'][si]['links'],r['links'][si]))
            if a['snapshots'][si]['verdict']!=r['verdicts'][si]: probs.append(('verdict',si,a['snapshots'][si]['verdict'],r['verdicts'][si]))
        # witness validity
        w=a['witness']
        faulty=set()
        for si,s in enumerate(x['snapshots']):
            q=w['demands'][si]
            loads={e['id']:Fraction(0) for e in x['edges']}
            met={}
            for c,v in zip(x['commodities'],q):
                met[('demand',c['id'])]=v
                W=sum(r['weight'] for r in c['routes'])
                for r in c['routes']:
                    amt=Fraction(v*r['weight'],W)
                    for e in r['edges']: loads[e]+=amt
            for n in x['nodes']:
                met[('ingress',n)]=sum(v for c,v in zip(x['commodities'],q) if c['source']==n)
                met[('egress',n)]=sum(v for c,v in zip(x['commodities'],q) if c['target']==n)
            for e in x['edges']: met[('link',e['id'])]=loads[e['id']]
            for o in s['observations']:
                if not (o['lower']<=met[(o['metric'],o['target'])]<=o['upper']):
                    if o['domain'] is None: probs.append(('trusted violated',))
                    faulty.add(o['domain'])
            if [str(loads[e['id']]) for e in x['edges']] != w['links'][si]: probs.append(('witness links',si,w['links'][si]))
            for ci,(lo,hi) in enumerate(s['bounds']):
                if not (lo<=q[ci]<=hi): probs.append(('witness bounds',))
        if set(w['faults'])!=faulty: probs.append(('witness faults',w['faults'],sorted(faulty)))
        if len(faulty)!=r['min_faults']: probs.append(('witness fault count',len(faulty),r['min_faults']))
        if a['status']=='unique':
            if a.get('alternative') is not None: probs.append(('alternative not null',))
        else:
            alt=a.get('alternative')
            if alt is None: probs.append(('alternative null',))
            else:
                if alt['demands']==w['demands']: probs.append(('alternative same',))
                # validate alt
                f2=set()
                for si,s in enumerate(x['snapshots']):
                    q=alt['demands'][si]
                    loads={e['id']:Fraction(0) for e in x['edges']}
                    for c,v in zip(x['commodities'],q):
                        W=sum(r['weight'] for r in c['routes'])
                        for r in c['routes']:
                            amt=Fraction(v*r['weight'],W)
                            for e in r['edges']: loads[e]+=amt
                    for o in s['observations']:
                        if o['metric']=='link': val=loads[o['target']]
                        elif o['metric']=='demand': val=q[[c['id'] for c in x['commodities']].index(o['target'])]
                        elif o['metric']=='ingress': val=sum(v for c,v in zip(x['commodities'],q) if c['source']==o['target'])
                        else: val=sum(v for c,v in zip(x['commodities'],q) if c['target']==o['target'])
                        if not (o['lower']<=val<=o['upper']):
                            if o['domain'] is None: probs.append(('alt trusted violated',))
                            f2.add(o['domain'])
                if set(alt['faults'])!=f2: probs.append(('alt faults',))
                if len(f2)!=r['min_faults']: probs.append(('alt fault count',len(f2)))
        if probs:
            bad+=1
            print('MISMATCH', probs)
            print(json.dumps(x))
            if bad>3: break
    print('done, mismatches:', bad, 'of', len(instances))
    return 0 if bad==0 else 1
sys.exit(main())
